reference_solution:
def minDays(bloomDay, m, k):
    if m * k > len(bloomDay):
        return -1
    def ok(day):
        flowers = bouquets = 0
        for b in bloomDay:
            if b <= day:
                flowers += 1
                if flowers == k:
                    bouquets += 1
                    flowers = 0
            else:
                flowers = 0
        return bouquets >= m
    lo, hi = min(bloomDay), max(bloomDay)
    while lo < hi:
        mid = (lo + hi) // 2
        if ok(mid):
            hi = mid
        else:
            lo = mid + 1
    return lo

