def minDays(bloomDay, m, k):
    def ok(day):
        flowers = bouquets = 0
        for b in bloomDay:
            if b <= day:
                flowers += 1
                if flowers == k:
                    bouquets += 1
                    flowers = 0
            else:
                flowers = 0
        return bouquets >= m
    for day in sorted(set(bloomDay)):
        if ok(day):
            return day
    return -1

